from pathlib import Path
import json,sys
expected=['S1_8K_OK','TEST=C005_P14','AP_READY=1','BAD_RETRIES=40','BAD_FORCE=1','BAD_ACCEPT=1','BAD_MIXED=1','GOOD_RETRIES=40','GOOD_FORCE=0','GOOD_ACCEPT_BEFORE=0','GOOD_ACCEPT_AFTER=1','GOOD_A=33','GOOD_B=44','AP_DONE=1','DONE']
trace=Path(sys.argv[1]).read_text(encoding='ascii',errors='replace').splitlines();checks={'trace_exact':trace==expected,'bad_budget_becomes_unsafe_repair':all(x in trace for x in ['BAD_RETRIES=40','BAD_FORCE=1','BAD_ACCEPT=1','BAD_MIXED=1']),'good_budget_does_not_create_authority':all(x in trace for x in ['GOOD_RETRIES=40','GOOD_FORCE=0','GOOD_ACCEPT_BEFORE=0','GOOD_ACCEPT_AFTER=1','GOOD_A=33','GOOD_B=44']),'two_cpu_participation':all(x in trace for x in ['AP_READY=1','AP_DONE=1'])};out={'format':'C005_P14_EVALUATION_V1','passed':all(checks.values()),'checks':checks,'trace':trace};Path(sys.argv[2]).write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(out,indent=2));raise SystemExit(0 if out['passed'] else 1)
